// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

// Load fonts at module level to ensure they are ready before frame 0
const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();
const { fontFamily: inter } = loadInter();



export type FloatingPerformanceMeterProps = Record<string, any>;

const FloatingPerformanceMeter: React.FC<FloatingPerformanceMeterProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  startColor = "#FF3333", // Bright Red
  endColor = "#00FF66",   // Bright Green
  trackColor = "rgba(255, 255, 255, 0.08)",
  metricText = "+10",
  label = "SYSTEM PERFORMANCE",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const gaugeStartFrame = 15;
  const textStartFrame = 45;

  // 1. Floating Animation (Continuous)
  const floatY = Math.sin((frame / fps) * 2) * 15;

  // 2. Gauge Progress Animation
  const gaugeProgress = spring({
    fps,
    frame: frame - gaugeStartFrame,
    config: {
      damping: 14,
      mass: 0.8,
      stiffness: 70,
    },
  });

  // 3. Gauge Color Interpolation (Red -> Yellow -> Green)
  const currentGaugeColor = interpolateColors(
    gaugeProgress,
    [0, 0.5, 1],
    [startColor, "#FFD700", endColor]
  );

  // 4. Metric Text Animation
  const textSpring = spring({
    fps,
    frame: frame - textStartFrame,
    config: {
      damping: 12,
      mass: 0.5,
      stiffness: 150,
    },
  });

  // Text scaling with a slight overshoot
  const textScale = interpolate(textSpring, [0, 1], [0.5, 1]);
  const textOpacity = interpolate(textSpring, [0, 0.8], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Dynamic glow based on text appearance
  const textGlowRadius = interpolate(textSpring, [0, 1], [0, 40], {
    extrapolateRight: "clamp",
  });

  // Background studio light flare
  const flareOpacity = interpolate(textSpring, [0, 1], [0, 0.15], {
    extrapolateRight: "clamp",
  });

  // Fade in the whole container smoothly
  const containerOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  // SVG Path Data (Semi-circle)
  // ViewBox: 0 0 800 450
  // Center: 400, 350
  // Radius: 300
  const svgPath = "M 100 350 A 300 300 0 0 1 700 350";
  const strokeWidth = 36;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Container with Floating Effect */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          position: "relative",
          width: 800,
          height: 500,
          opacity: containerOpacity,
          transform: `translateY(${floatY}px)`,
          transition: "none",
        }}
      >
        {/* Studio Light Flare behind the UI */}
        <div
          style={{
            position: "absolute",
            width: 600,
            height: 400,
            borderRadius: "50%",
            background: `radial-gradient(circle, ${currentGaugeColor} 0%, rgba(0,0,0,0) 70%)`,
            opacity: flareOpacity,
            filter: "blur(60px)",
            top: "10%",
            zIndex: 0,
            transition: "none",
          }}
        />

        {/* The Speedometer SVG */}
        <svg
          width="100%"
          height="450"
          viewBox="0 0 800 450"
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            zIndex: 1,
            overflow: "visible",
            transition: "none",
          }}
        >
          {/* Base Track */}
          <path
            d={svgPath}
            stroke={trackColor}
            strokeWidth={strokeWidth}
            fill="none"
            strokeLinecap="round"
            style={{ transition: "none" }}
          />

          {/* Glowing Filter Definition */}
          <defs>
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="12" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Animated Fill Track */}
          <path
            d={svgPath}
            stroke={currentGaugeColor}
            strokeWidth={strokeWidth}
            fill="none"
            strokeLinecap="round"
            pathLength="100"
            strokeDasharray="100"
            strokeDashoffset={100 - gaugeProgress * 100}
            filter="url(#glow)"
            style={{ transition: "none" }}
          />

          {/* Bright leading tip of the gauge */}
          <path
            d={svgPath}
            stroke="#FFFFFF"
            strokeWidth={strokeWidth - 20}
            fill="none"
            strokeLinecap="round"
            pathLength="100"
            strokeDasharray="0.1 100"
            strokeDashoffset={100 - gaugeProgress * 100}
            style={{ transition: "none", opacity: gaugeProgress > 0.05 ? 1 : 0 }}
          />
        </svg>

        {/* Text Elements */}
        <div
          style={{
            position: "absolute",
            bottom: 80, // Position relative to the center of the arc
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            zIndex: 2,
            transition: "none",
          }}
        >
          {/* Main Metric (+10) */}
          <div
            style={{
              fontFamily: spaceGrotesk,
              fontSize: 160,
              fontWeight: 800,
              color: "#FFFFFF",
              lineHeight: 1,
              transform: `scale(${textScale})`,
              opacity: textOpacity,
              textShadow: `0 0 ${textGlowRadius}px ${currentGaugeColor}, 0 0 ${
                textGlowRadius * 2
              }px ${currentGaugeColor}`,
              transition: "none",
              letterSpacing: "-0.04em",
            }}
          >
            {metricText}
          </div>

          {/* Label */}
          <div
            style={{
              fontFamily: inter,
              fontSize: 24,
              fontWeight: 600,
              color: "rgba(255, 255, 255, 0.6)",
              marginTop: 16,
              letterSpacing: "0.2em",
              opacity: interpolate(textOpacity, [0, 1], [0, 1]), // Follows main text opacity
              transform: `translateY(${interpolate(
                textSpring,
                [0, 1],
                [10, 0]
              )}px)`,
              transition: "none",
            }}
          >
            {label}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FloatingPerformanceMeter;